import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        long answer = 0;
        int[] count = new int[7];
        for (int start = 0; start < n; start++) {
            // A valid substring has at most 7 letters each used at most 7 times: length <= 49.
            Arrays.fill(count, 0);
            int distinct = 0, maximum = 0;
            for (int end = start; end < Math.min(n, start + 49); end++) {
                int k = s.charAt(end) - 'a';
                if (count[k]++ == 0) distinct++;
                maximum = Math.max(maximum, count[k]);
                if (maximum <= distinct) answer++;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s := token()
	n := len(s)
	answer := 0
	for start := 0; start < n; start++ {
		// A valid substring has at most 7 letters each used at most 7 times: length <= 49.
		var count [7]int
		distinct, maximum := 0, 0
		for end := start; end < min(n, start+49); end++ {
			k := s[end] - 'a'
			if count[k] == 0 {
				distinct++
			}
			count[k]++
			maximum = max(maximum, count[k])
			if maximum <= distinct {
				answer++
			}
		}
	}
	fmt.Println(answer)
}
